import{_ as a,o as e,c as d,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"RAG 与记忆总览","description":"","frontmatter":{"title":"RAG 与记忆总览"},"headers":[],"relativePath":"ts-ai/knowledge/index.md","filePath":"ts-ai/knowledge/index.md","lastUpdated":1786113687000}'),r={name:"ts-ai/knowledge/index.md"};function s(i,t,o,l,h,p){return e(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="rag-与记忆总览" tabindex="-1">RAG 与记忆总览 <a class="header-anchor" href="#rag-与记忆总览" aria-label="Permalink to &quot;RAG 与记忆总览&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>用检索增强生成（RAG）回答「知识库里有什么」；用记忆回答「这个用户/会话之前怎样」。两者都不要和「把一切塞进 Prompt」混为一谈。</p><p>前置：<a href="/ts-ai/agent/">Agent 开发</a>（会调模型与组链）；服务端上传/落库见 <a href="/ts-ai/backend/">服务端工程</a>。</p><p><strong>怎么读：</strong></p><ol><li>先读 <a href="/ts-ai/knowledge/rag-foundations/rag-principles-boundaries">RAG 原理与边界</a></li><li>立刻跑 <a href="/ts-ai/knowledge/rag-foundations/minimal-rag-skeleton">最小可运行 RAG</a></li><li>再按文档处理 → 检索 → LangChain RAG 深入</li><li><strong>高级 RAG 为进阶</strong>，基础不通不要先啃</li><li>记忆与 RAG 分开学；最后用 <a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">组装配方与自检</a> 收束</li></ol><h2 id="分组地图" tabindex="-1">分组地图 <a class="header-anchor" href="#分组地图" aria-label="Permalink to &quot;分组地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>你在学什么</th><th>优先级</th></tr></thead><tbody><tr><td><a href="/ts-ai/knowledge/rag-foundations/">RAG 基础</a></td><td>原理、边界、最小可跑通链路</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/knowledge/document-processing/">文档处理</a></td><td>加载、清洗、Chunk、入库流水线、增量更新</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/knowledge/retrieval/">检索系统</a></td><td>Embedding、pgvector、过滤、混合检索、重排、权限与评测</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/knowledge/rag-engineering/">LangChain.js RAG</a></td><td>Document/Retriever、Chain、上下文组装、引用、流式、测试</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/knowledge/advanced-rag/">高级 RAG</a></td><td>改写、多步、Agentic、Graph、多模态</td><td><strong>进阶</strong></td></tr><tr><td><a href="/ts-ai/knowledge/memory/">记忆系统</a></td><td>短/长期记忆、Checkpoint/Store、提取更新、租户隔离</td><td><strong>必学</strong>（可与 RAG 基础并行）</td></tr><tr><td><a href="/ts-ai/knowledge/assembly/">组装配方与能力自检</a></td><td>场景配方、跨组自检、进集成前收束</td><td><strong>必学</strong>（模块末）</td></tr></tbody></table><h2 id="跨章所有权" tabindex="-1">跨章所有权 <a class="header-anchor" href="#跨章所有权" aria-label="Permalink to &quot;跨章所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>本模块讲</th><th>别章讲</th></tr></thead><tbody><tr><td>Embedding 概念</td><td>检索侧用法、索引与查询一致性</td><td><a href="/ts-ai/foundations/model/multimodal-tools-embeddings">多模态、工具与 Embedding</a></td></tr><tr><td>文件上传入口</td><td>Ingestion 管道、索引状态</td><td><a href="/ts-ai/backend/api-realtime/file-upload">文件上传</a>；UI → <a href="/ts-ai/integration/vue-nuxt/file-upload-indexing-state">integration</a></td></tr><tr><td>Checkpoint / Store</td><td>记忆语义、读写时机、与对话历史关系</td><td><a href="/ts-ai/workflow/durable-execution/checkpoint-store">图持久化：Checkpointer 与 Checkpoint</a> 图持久执行</td></tr><tr><td>权限 / 租户</td><td>检索过滤、记忆隔离</td><td><a href="/ts-ai/quality/security-governance/authentication-authorization">认证与授权</a>；<a href="/ts-ai/backend/ai-service/request-context-tenancy">请求 Context</a></td></tr><tr><td>Agentic 检索</td><td>何时用工具检索、模式边界</td><td><a href="/ts-ai/agent/runtime/">Agent Runtime</a>、<a href="/ts-ai/agent/tools-mcp/">工具与 MCP</a></td></tr><tr><td>评测门禁</td><td>检索/RAG 测试方法</td><td>全站回归 → <a href="/ts-ai/quality/">质量与生产</a></td></tr></tbody></table><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原理与边界 → 最小可运行 RAG</span></span>
<span class="line"><span>  → 文档处理 → 检索系统 → LangChain.js RAG</span></span>
<span class="line"><span>  →（可选）高级 RAG</span></span>
<span class="line"><span>  → 记忆系统 → 组装配方与自检</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="和「只把-pdf-塞进-prompt」的区别" tabindex="-1">和「只把 PDF 塞进 Prompt」的区别 <a class="header-anchor" href="#和「只把-pdf-塞进-prompt」的区别" aria-label="Permalink to &quot;和「只把 PDF 塞进 Prompt」的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>长上下文硬塞</th><th>RAG</th><th>记忆</th></tr></thead><tbody><tr><td>解决什么</td><td>单次读完少量材料</td><td>从大知识库按需召回</td><td>跨轮次偏好/事实/状态</td></tr><tr><td>主要成本</td><td>Token</td><td>索引 + 检索 + 生成</td><td>写入策略与隐私</td></tr><tr><td>失败样子</td><td>超窗截断</td><td>召回错/编造无引用</td><td>记错、泄漏、过期</td></tr></tbody></table>`,14)])])}const b=a(r,[["render",s]]);export{g as __pageData,b as default};
